import java.util.*;

public class C2NTask2 {

    public static List<Integer> middleSlice(List<Integer> list) {
        int size = list.size();
        if (size < 2) return list.subList(0, size);
        int from = size / 4;
        int to = size - size / 4;
        return list.subList(from, to);
    }

