public class C2NTask5 {

    public static List<String> createSyncList(String... items) {
        List<String> base = new ArrayList<>(Arrays.asList(items));
        return Collections.synchronizedList(base);
    }

    public static int safeCount(List<String> syncList) {
        synchronized (syncList) {
            int count = 0;
            for (String s : syncList) {
                if (s != null && !s.isEmpty()) count++;
            }
            return count;
        }
    }

