public static <T> List<List<T>> groupConsecutive(List<T> input) {
    List<List<T>> result = new ArrayList<>();
    if (input.isEmpty()) return result;
    List<T> cur = new ArrayList<>(Arrays.asList(input.get(0)));
    for (int i = 1; i < input.size(); i++) {
        if (input.get(i).equals(cur.get(cur.size() - 1))) { cur.add(input.get(i)); }
        else { result.add(cur); cur = new ArrayList<>(Arrays.asList(input.get(i))); }
    }
    result.add(cur);
    return result;
}

