public class C2NTask50 {

    // Generates all valid combinations of n pairs of balanced parentheses.
    // Returns them in lexicographic order (where '(' < ')').
    // For n=0, returns a list containing exactly one element: the empty string "".
    // For n<0, returns an empty list.
    // Must use backtracking (not iterative generation).
    public static List<String> generateParentheses(int n) {

