        assert generateParentheses(0).equals(List.of("")) : "n=0 => empty string";
        assert generateParentheses(1).equals(List.of("()")) : "n=1";
        assert generateParentheses(2).equals(List.of("(())", "()()")) : "n=2";
        assert generateParentheses(3).size() == 5 : "n=3 has 5 combos";
        assert generateParentheses(3).get(0).equals("((()))") : "first is ((()))";
        assert generateParentheses(-1).isEmpty() : "negative => empty";
